code:
//! Detect records that hold more than one EXTRACTABLE pure-leaf function — the "each method a single
//! record" ideal, measured (`bsc-graph-detects-multi-method-records`).
//!
//! A blunt function count is useless: 612/694 algorithm records have >1 `fn`, but that count includes
//! `impl` methods, inline `#[cfg(test)]` fns, and — the reason it misleads — CLI dispatchers and cohesive
//! STATEFUL modules that must NOT be split (`epic-command-surfaces-are-nodes` Decision 3: only PURE/LEAF
//! functions are extraction targets; stateful modules stay whole). The signal that matters is how many
//! **extractable pure-leaf** free functions a record carries.
//!
//! The classifier is deliberately CONSERVATIVE — it flags only high-confidence pure leaves, because a
//! false positive makes the worklist noise and the drift gate a nuisance. It under-reports rather than
//! over-reports: a pure function that merely mentions a state/IO token is left off, not wrongly listed.
//! Deterministic and zero-egress: tree-sitter parses locally, the walk is order-stable.

pub(crate) use language_for::language_for;
pub(crate) use is_test_attributed::is_test_attributed;
pub(crate) use fn_name::fn_name;
pub(crate) use module_defined_types::module_defined_types;
pub(crate) use leaf_signature::leaf_signature;
pub(crate) use private_item_names::private_item_names;
pub(crate) use body_references_private::body_references_private;
pub(crate) use cohesion_reason::cohesion_reason;
pub(crate) use is_candidate_record::is_candidate_record;
pub use worklist::worklist;
pub use demoted::demoted;
pub use counts::counts;
pub use drift_against::drift_against;

use serde_json::Value;
use std::collections::BTreeMap;
use tree_sitter::{Node, Parser};

/// Tokens whose presence in a function's TEXT disqualifies it as a pure leaf — shared state, interior
/// mutability, IO, effects, and async. Value types that can be pure parameters (`SystemTime`, `Path`,
/// `Duration`) are deliberately ABSENT; only the impure `::now()`/IO forms are caught, so a pure rule
/// that takes a `SystemTime` in and returns a decision still counts.
const IMPURE_MARKERS: &[&str] = &[
    // shared state / interior mutability
    "Mutex", "RwLock", "OnceLock", "OnceCell", "lazy_static", "thread_local", "AtomicUsize",
    "AtomicBool", "AtomicU", "AtomicI", "RefCell", "Cell<", ".lock(", ".borrow(", "static mut ",
    // IO / effects / clocks — impurity, not the value types
    "std::fs", "std::process", "std::env", "File::", "Command", "std::io", "print!", "println!",
    "eprint", "fs::", "process::", "env::", "Connection", "::now(", "read_to_string", "write_all",
    "spawn", "thread::", "TcpStream", "TcpListener", "Instant", "SystemTime::",
    // async — not a synchronous leaf
    ".await", "async fn", "async move", "tokio::",
];

/// Is this top-level `function_item` a high-confidence extractable pure leaf?
/// Attributes whose macro EMITS SIBLING ITEMS beside the function, so moving the function to another
/// module leaves the generated items behind and the crate stops compiling.
///
/// `#[tauri::command]` generates `__cmd__<name>` and `__tauri_command_name_<name>` in the module that
/// holds the function, and `tauri::generate_handler![module::name]` resolves them THERE. Move the
/// function into a child record and the handler names a module that no longer has them:
///
/// ```text
/// error[E0433]: cannot find `__cmd__record_attestations` in `attest`
/// ```
///
/// MEASURED on the method-leaf backlog: 24 such functions across 12 records were proposed as
/// extractable, and moving them produced 60 errors in `base-studio-code`. The classifier is the right
/// seam for this rather than the verb, because `extract` REUSES it — so the worklist stops proposing
/// them and the verb stops accepting them from one change.
///
/// A named list, not a heuristic: the property is "this macro emits siblings", which cannot be read off
/// the attribute's shape, and a heuristic broad enough to catch it would exclude honest leaves.
const ITEM_GENERATING_ATTRS: [&str; 1] = ["tauri::command"];

/// Does a top-level `function_item` carry an attribute from [`ITEM_GENERATING_ATTRS`]?
fn generates_sibling_items(node: Node, src: &[u8]) -> bool {
    let mut sib = node.prev_sibling();
    while let Some(s) = sib {
        match s.kind() {
            "attribute_item" => {
                let t = s.utf8_text(src).unwrap_or("");
                if ITEM_GENERATING_ATTRS.iter().any(|a| t.contains(a)) {
                    return true;
                }
                sib = s.prev_sibling();
            }
            // Comments and blank lines sit between an attribute and its item; keep scanning past them,
            // but stop at the previous real item. Same walk as `is_test_attributed`.
            "line_comment" | "block_comment" => sib = s.prev_sibling(),
            _ => break,
        }
    }
    false
}

fn is_extractable_leaf(node: Node, src: &[u8]) -> bool {
    let text = node.utf8_text(src).unwrap_or("");
    if text.is_empty() {
        return false;
    }
    if generates_sibling_items(node, src) {
        return false;
    }
    // A `super::` PATH CHANGES MEANING WHEN THE FUNCTION MOVES. In the flat record `super` is the
    // crate module's parent; in a child record it is the parent RECORD, one level deeper, so
    // `super::studio_ws::…` resolves to nothing:
    //
    //     error[E0433]: cannot find `studio_ws` in `super`
    //
    // Rewriting to `super::super::` would be mechanical but it is a guess about which level was meant,
    // and this verb refuses rather than guesses everywhere else. MEASURED on the method-leaf backlog:
    // 3 functions in 1 record of 39, so the cost of refusing is small and the cost of guessing is a
    // silently wrong path. `use super::*;` — which `extract` itself inserts — is a `use`, not a body
    // path, and is unaffected.
    if text.contains("super::") {
        return false;
    }
    if IMPURE_MARKERS.iter().any(|m| text.contains(m)) {
        return false;
    }
    // A leaf takes values and returns one. A `&mut` parameter that is not `&mut self` is still a mutation
    // of caller state threaded through — treat it as coupling and leave it out (conservative).
    if let Some(params) = node.child_by_field_name("parameters") {
        let p = params.utf8_text(src).unwrap_or("");
        if p.contains("self") || p.contains("&mut ") {
            return false;
        }
    }
    true
}

/// The extractable pure-leaf function names in one record's `code`, in source order. Empty for a record
/// whose tech has no classifier, or that parses to nothing.
pub fn extractable_leaves(code: &str, tech: &str) -> Vec<String> {
    let Some(lang) = language_for(tech) else {
        return Vec::new();
    };
    let mut parser = Parser::new();
    if parser.set_language(&lang).is_err() {
        return Vec::new();
    }
    let Some(tree) = parser.parse(code, None) else {
        return Vec::new();
    };
    let src = code.as_bytes();
    let root = tree.root_node();
    let mut out = Vec::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        // TOP-LEVEL free functions only. `impl` methods live under `impl_item`, and test fns under
        // `mod_item` — neither is a direct child of `source_file`, so both are excluded by construction.
        if child.kind() != "function_item" {
            continue;
        }
        if is_test_attributed(child, src) {
            continue;
        }
        if is_extractable_leaf(child, src) {
            if let Some(name) = fn_name(child, src) {
                out.push(name);
            }
        }
    }
    // A NAME CARRIED BY TWO TOP-LEVEL FUNCTIONS CANNOT BE EXTRACTED — both would become the same child
    // record id, so one would silently overwrite the other. In practice these are `#[cfg]`-gated
    // variants of one function (`signal_number` for two platforms), which are a single module's
    // business and not a decomposition target at all. MEASURED: 2 records on the backlog carry them.
    //
    // Both copies go, not just the duplicate: keeping one would propose extracting half of a cfg pair.
    let mut seen: std::collections::BTreeMap<String, usize> = Default::default();
    for n in &out {
        *seen.entry(n.clone()).or_default() += 1;
    }
    out.retain(|n| seen.get(n) == Some(&1));
    out
}

/// One record's extractable-leaf finding.
#[derive(Debug, Clone)]
pub struct RecordLeaves {
    pub id: String,
    pub names: Vec<String>,
}

/// The decomposition TRANSFORM behind `bsc graph extract`. Kept in an INNER module so its helpers
/// are not top-level free functions of `methods` (the drift classifier counts only module-scope
/// leaves), while `use super::*` still reaches this module's private detection helpers.
pub use extract_transform::{plan_extraction, ExtractionPlan};

mod extract_transform {
use super::*;

// ===================================================================================================
// The decomposition TRANSFORM — `bsc graph extract`. Automates the per-method decomposition template a
// worker runs by hand today (requests #249/#250): a flat record holding several pure-leaf free
// functions becomes a `--mod.rs` dir-module parent that re-exports one child record per function.
//
// PURE. `plan_extraction` reads the flat record and returns records; it touches no store and no
// filesystem. The CLI seam applies the plan to the committed repo store, so the transform is provable
// on a fixture the same way the detection above is. It REUSES that detection — `is_extractable_leaf`,
// `body_references_private`, `private_item_names` — so the verb refuses exactly the functions the
// worklist would never have proposed, and names WHY.
// ===================================================================================================

/// The record id that materializes a module at repo-relative `src`, mirroring
/// `graph_materialize::plan::expected_id` (a dev-dependency — unreachable from this runtime code, so the
/// one rule both must agree on is restated here and pinned by a test). Kebab each segment after `src/`,
/// join with `--`, prepend the kebabed crate dir. Rust module names are snake_case, so kebabing is a
/// `_`→`-` swap. An id whose underscores were NOT hyphenated SILENTLY fails to materialize (the emitter
/// compares against exactly this), so every id the plan mints is derived HERE from the src it will land
/// at, never spelled by hand.
fn record_id_for(src: &str) -> Option<String> {
    let stem = src.strip_suffix(".rs")?;
    let idx = stem.find("/src/")?;
    let crate_dir = stem[..idx].rsplit('/').next().filter(|s| !s.is_empty())?;
    let rest = &stem[idx + "/src/".len()..];
    let mut segs = vec![crate_dir.replace('_', "-")];
    segs.extend(rest.split('/').filter(|s| !s.is_empty()).map(|s| s.replace('_', "-")));
    Some(format!("{}.rs", segs.join("--")))
}

/// The visibility modifier VERBATIM on a top-level item, canonically spaced (`pub(crate)`), or
/// `"private"` when the item declares none.
fn item_vis(node: Node, src: &[u8]) -> String {
    let mut c = node.walk();
    for ch in node.children(&mut c) {
        if ch.kind() == "visibility_modifier" {
            return ch.utf8_text(src).unwrap_or("pub").split_whitespace().collect::<String>();
        }
    }
    "private".to_string()
}

/// Byte offset where an item's leading doc-comment / attribute block starts — so a function extracts
/// WITH its `///` docs and `#[…]` attributes, not stripped of them. Walks contiguous `attribute_item`
/// and comment siblings immediately above the item, stopping at the previous real item or a blank-line
/// gap (a comment separated from the fn by a blank line belongs to whatever is above it, not to the fn).
fn item_lead_start(node: Node, src: &[u8]) -> usize {
    let mut start = node.start_byte();
    let mut sib = node.prev_sibling();
    while let Some(s) = sib {
        if !matches!(s.kind(), "attribute_item" | "line_comment" | "block_comment") {
            break;
        }
        // A blank line between this sibling and what currently begins the block detaches it.
        let between = std::str::from_utf8(&src[s.end_byte()..start]).unwrap_or("");
        if between.matches('\n').count() > 1 {
            break;
        }
        start = s.start_byte();
        sib = s.prev_sibling();
    }
    start
}

/// Names brought into module scope by top-level `use` declarations — the last path segment of a simple
/// `use a::b::C`, and every leaf of a `use a::{B, c::D}` list. Crude by design: a child that references
/// any of them needs `use super::*`, and over-reporting only adds a harmless glob import (an unused
/// `use super::*` is not linted).
fn imported_names(root: Node, src: &[u8]) -> std::collections::HashSet<String> {
    let mut names = std::collections::HashSet::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if child.kind() != "use_declaration" {
            continue;
        }
        // Every identifier / type_identifier under the use tree; the final segments are what land in
        // scope, and incidental path roots do no harm in a set used only for a membership test.
        collect_idents(child, src, &mut names);
    }
    names
}

/// Every `identifier` / `type_identifier` leaf under `node` — used to gather what a `use` brings in.
fn collect_idents(node: Node, src: &[u8], into: &mut std::collections::HashSet<String>) {
    if matches!(node.kind(), "identifier" | "type_identifier") {
        into.insert(node.utf8_text(src).unwrap_or_default().to_string());
    }
    let mut c = node.walk();
    for ch in node.children(&mut c) {
        collect_idents(ch, src, into);
    }
}

/// Top-level item names of any visibility — fn / struct / enum / const / static / type / union / trait.
/// A child that names one of these needs `use super::*` to reach it (a glob re-exports the pub ones;
/// referencing a PRIVATE one is refused earlier).
fn top_level_item_names(root: Node, src: &[u8]) -> std::collections::HashSet<String> {
    let mut names = std::collections::HashSet::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if !matches!(
            child.kind(),
            "function_item" | "struct_item" | "enum_item" | "const_item" | "static_item"
                | "type_item" | "union_item" | "trait_item"
        ) {
            continue;
        }
        if let Some(nm) = child.child_by_field_name("name") {
            names.insert(nm.utf8_text(src).unwrap_or_default().to_string());
        }
    }
    names
}

/// Does `body` reference `name` as a whole-word identifier, other than `own`? Same tokenizer as
/// [`body_references_private`], so `add` inside `address` does not match.
fn references_name(body: &str, own: &str, name: &str) -> bool {
    body.split(|c: char| !c.is_alphanumeric() && c != '_').any(|tok| tok != own && tok == name)
}

/// Byte offset just past the module's leading PREAMBLE — its `//!` header and any inner attributes —
/// or 0 when the module opens with neither. The re-exports are inserted here so they sit after the
/// preamble and before the module body.
///
/// INNER ATTRIBUTES ARE PART OF IT, and leaving them out produced code that does not compile. An
/// inner attribute must precede every item in its module, so inserting `pub use` above a `#![allow(…)]`
/// moves the attribute after an item:
///
/// ```text
/// error: an inner attribute is not permitted in this context
/// ```
///
/// MEASURED on the extraction backlog: 1 of 39 records (`bsc-github--repo-credentials.rs`) carried one,
/// and it broke the workspace build. Blank lines and ordinary `//` comments are tolerated INSIDE the
/// run, because an attribute is routinely preceded by a comment explaining it — but they do not
/// themselves extend the preamble, since a `//` comment directly above an item belongs to that item and
/// the re-exports must not be wedged between the two.
fn header_end_byte(code: &str) -> usize {
    let mut off = 0usize;
    let mut header_end = 0usize;
    for line in code.split_inclusive('\n') {
        let t = line.trim_start();
        if t.starts_with("//!") || t.starts_with("#![") {
            off += line.len();
            header_end = off;
        } else if t.trim().is_empty() || t.starts_with("//") {
            // Tolerated INSIDE the run but not part of it: only a `//!` or `#![` line moves the end,
            // so a comment attached to the first real item stays attached to it.
            off += line.len();
        } else {
            break;
        }
    }
    header_end
}

/// Collapse 3+ consecutive newlines to 2 and guarantee exactly one trailing newline — tidies the blank
/// runs left where a moved function used to sit, so the parent reads as if hand-decomposed.
fn tidy(mut s: String) -> String {
    while s.contains("\n\n\n") {
        s = s.replace("\n\n\n", "\n\n");
    }
    let trimmed = s.trim_end().to_string();
    format!("{trimmed}\n")
}

/// The refusal reason for extracting `node` (a named top-level free fn), or `None` if it is a clean pure
/// leaf that also does not reach a private parent item that stays behind. Reuses the same predicates the
/// worklist classifier uses, so `extract` refuses exactly what the worklist would never have proposed —
/// and says WHY, so the human picks a different function rather than getting a guess.
fn extraction_refusal(
    node: Node,
    src: &[u8],
    private_targets: &std::collections::HashSet<String>,
) -> Option<String> {
    let text = node.utf8_text(src).unwrap_or("");
    if text.is_empty() {
        return Some("its body could not be read".to_string());
    }
    if let Some(m) = IMPURE_MARKERS.iter().find(|m| text.contains(**m)) {
        return Some(format!(
            "it is not a pure leaf — its body uses `{m}` (shared state / IO / effect / async). Only pure \
             free functions extract cleanly; a stateful or effectful one stays with the module"
        ));
    }
    if let Some(params) = node.child_by_field_name("parameters") {
        let p = params.utf8_text(src).unwrap_or("");
        if p.contains("self") {
            return Some("it is a method (takes `self`), not a free function".to_string());
        }
        if p.contains("&mut ") {
            return Some(
                "it takes a `&mut` parameter — it threads caller state through, so it is not a pure leaf"
                    .to_string(),
            );
        }
    }
    let name = fn_name(node, src).unwrap_or_default();
    if body_references_private(text, &name, private_targets) {
        return Some(format!(
            "it references a PRIVATE item of the module that would stay behind — a glob re-export reaches \
             only the pub items, so `{name}` cannot travel on its own. Extract that helper in the same \
             call, or leave `{name}` in the module"
        ));
    }
    None
}

/// A decomposition plan: the rewritten `--mod.rs` parent record and one child record per extracted
/// function. The CLI applies it to the committed repo store; nothing here reads or writes.
#[derive(Debug, Clone)]
pub struct ExtractionPlan {
    /// The flat record id being decomposed — removed from the store as the plan lands.
    pub flat_id: String,
    /// The rewritten dir-module parent (`…--mod.rs`).
    pub parent: Value,
    /// One child record per extracted function, in the order named.
    pub children: Vec<Value>,
}

/// Plan the decomposition of one flat `record` into a `--mod.rs` dir-module, extracting each function in
/// `fn_names` into its own child record. PURE — see [`ExtractionPlan`].
///
/// Refuses (never guesses) when a named function is not a pure free-fn leaf, or reaches a private parent
/// item that would stay behind, naming WHY so the caller picks differently. Scope is the COMMON case —
/// pure free-fn → child, the exact shape the by-hand decompose forks produced. It does not attempt to
/// split a stateful module, move an `impl` method, or reason about macro-generated items.
pub fn plan_extraction(record: &Value, fn_names: &[String]) -> Result<ExtractionPlan, String> {
    let flat_id = record.get("id").and_then(Value::as_str).ok_or("record has no `id`")?.to_string();
    let tech = record.get("tech").and_then(Value::as_str).unwrap_or("");
    if tech != "rust" {
        return Err(format!(
            "extract supports Rust only (record `{flat_id}` is tech `{tech}`) — the decomposition template \
             is the Rust crate-module one"
        ));
    }
    let code = record.get("code").and_then(Value::as_str).ok_or("record has no `code`")?;
    let src = record.get("src").and_then(Value::as_str).ok_or_else(|| {
        format!("record `{flat_id}` has no `src` — a dir-module's child paths derive from it")
    })?;
    if flat_id.ends_with("--mod.rs") {
        return Err(format!("`{flat_id}` is already a `--mod.rs` dir-module, not a flat record"));
    }
    // The id must be the one its own `src` materializes to, or the children this plan mints (derived the
    // same way) would silently fail to materialize. Catch a mismatched store up front.
    match record_id_for(src) {
        Some(expected) if expected == flat_id => {}
        Some(expected) => {
            return Err(format!(
                "record `{flat_id}` has src `{src}`, which materializes id `{expected}` — the record is \
                 mis-keyed, so a decomposition derived from its src would not compile"
            ));
        }
        None => return Err(format!("cannot derive a module id from src `{src}` (expected `…/src/…​.rs`)")),
    }
    if fn_names.is_empty() {
        return Err("name at least one function to extract with --fn <name>[,<name>…]".to_string());
    }
    // MODULE INCEPTION. A leaf whose name matches the record's own module produces `mod x` inside
    // `mod x`, which clippy denies workspace-wide:
    //
    //     error: module has the same name as its containing module
    //
    // MEASURED on the method-leaf backlog: `bsc-ui--validate-value.rs::validate_value` and
    // `logs--pending.rs::pending`, 2 of 111 leaves. Refused rather than renamed, because the child
    // record's id IS its module path and a name the caller did not ask for is a guess — the same
    // stance this verb takes on every other shape it will not decompose.
    let own_module = flat_id.rsplit("--").next().unwrap_or_default().trim_end_matches(".rs");
    if let Some(clash) = fn_names.iter().find(|n| n.replace('_', "-") == own_module) {
        return Err(format!(
            "`{clash}` has the same name as its module (`{own_module}`), so extracting it would produce              `mod {clash}` inside `mod {own_module}` — clippy's `module_inception`, denied workspace-wide.              Extract the other leaves, or rename the function first."
        ));
    }

    let lang = language_for(tech).ok_or_else(|| format!("no classifier for tech `{tech}`"))?;
    let mut parser = Parser::new();
    parser.set_language(&lang).map_err(|e| format!("tree-sitter: {e}"))?;
    let tree = parser.parse(code, None).ok_or("could not parse the record's code")?;
    let bytes = code.as_bytes();
    let root = tree.root_node();

    let want: std::collections::HashSet<&str> = fn_names.iter().map(String::as_str).collect();
    // Private parent items that are NOT themselves being extracted — the ones that stay behind. A leaf
    // reaching one of these is refused (same rule as the worklist's cohesion check).
    let private_targets: std::collections::HashSet<String> =
        private_item_names(root, bytes).into_iter().filter(|n| !want.contains(n.as_str())).collect();
    // What a child might need `use super::*` to reach: parent items (any vis) and use-imports, plus the
    // OTHER extracted names, which are re-exported at the parent.
    let mut parent_scope = top_level_item_names(root, bytes);
    parent_scope.extend(imported_names(root, bytes));
    parent_scope.extend(fn_names.iter().cloned());

    // Locate each named top-level free function, in the order requested, refusing with a reason.
    struct Located<'a> {
        name: String,
        node: Node<'a>,
    }
    let mut located: Vec<Located> = Vec::new();
    for want_name in fn_names {
        let mut hit: Option<Node> = None;
        let mut cursor = root.walk();
        for child in root.children(&mut cursor) {
            if child.kind() != "function_item" {
                continue;
            }
            if fn_name(child, bytes).as_deref() == Some(want_name.as_str()) {
                hit = Some(child);
                break;
            }
        }
        let node = hit.ok_or_else(|| {
            format!("no top-level free function `{want_name}` in `{flat_id}` (it is not a `fn` at module scope)")
        })?;
        if let Some(reason) = extraction_refusal(node, bytes, &private_targets) {
            return Err(format!("cannot extract `{want_name}`: {reason}"));
        }
        located.push(Located { name: want_name.clone(), node });
    }

    let dir = src.strip_suffix(".rs").unwrap_or(src); // "crates/<crate>/src/<X>"
    let feature = record.get("feature").cloned();

    // ---- children ----
    let mut children = Vec::new();
    for l in &located {
        let vis = item_vis(l.node, bytes);
        let lead = item_lead_start(l.node, bytes);
        let fn_start = l.node.start_byte();
        let end = l.node.end_byte();
        let lead_text = &code[lead..fn_start];
        let fn_text = &code[fn_start..end];
        // A private fn becomes `pub(crate) fn` so the parent can re-export it; a declared vis is kept.
        let bumped = if vis == "private" {
            format!("pub(crate) {fn_text}")
        } else {
            fn_text.to_string()
        };
        let needs_super = parent_scope.iter().any(|n| references_name(fn_text, &l.name, n));
        let mut body = String::new();
        if needs_super {
            body.push_str("use super::*;\n\n");
        }
        body.push_str(lead_text);
        body.push_str(&bumped);
        let body = tidy(body);

        let child_src = format!("{dir}/{}.rs", l.name);
        let child_id = record_id_for(&child_src)
            .ok_or_else(|| format!("cannot derive a child id for `{}`", l.name))?;
        // child -> child: this fn calls another extracted fn (now a sibling module).
        let composes: Vec<Value> = located
            .iter()
            .filter(|o| o.name != l.name && references_name(fn_text, &l.name, &o.name))
            .filter_map(|o| record_id_for(&format!("{dir}/{}.rs", o.name)).map(Value::String))
            .collect();

        let mut child = serde_json::json!({
            "id": child_id,
            "tech": "rust",
            "role": "algorithm",
            "name": l.name,
            "src": child_src,
            "folder": dir,
            "moduleVis": "private",
            "composes": composes,
            "code": body,
        });
        if let Some(f) = &feature {
            child["feature"] = f.clone();
        }
        children.push(child);
    }

    // ---- parent ----
    // Strip each moved fn (docs/attrs..end) from the code, largest offset first so earlier ranges hold.
    let mut ranges: Vec<(usize, usize)> =
        located.iter().map(|l| (item_lead_start(l.node, bytes), l.node.end_byte())).collect();
    ranges.sort_by_key(|a| std::cmp::Reverse(a.0));
    let mut stripped = code.to_string();
    for (s, e) in ranges {
        stripped.replace_range(s..e, "");
    }
    // Re-export block, in the order named — `pub use` for a pub fn, else `pub(crate) use`.
    let reexports: String = located
        .iter()
        .map(|l| {
            let vis = item_vis(l.node, bytes);
            let use_vis = if vis == "pub" { "pub" } else { "pub(crate)" };
            format!("{use_vis} use {name}::{name};", name = l.name)
        })
        .collect::<Vec<_>>()
        .join("\n");
    let h = header_end_byte(&stripped);
    let parent_code = if h == 0 {
        format!("{reexports}\n\n{stripped}")
    } else {
        format!("{}\n{reexports}\n{}", &stripped[..h], &stripped[h..])
    };
    let parent_code = tidy(parent_code);

    // `#[allow(unused_imports)]` only when a re-export is CONSUMER-ONLY — the fn is not referenced in the
    // retained parent body, so the `pub use` would otherwise trip `unused_imports` under `-D warnings`.
    let consumer_only = located
        .iter()
        .any(|l| !references_name(&stripped, "", &l.name));

    let parent_src = format!("{dir}/mod.rs");
    let parent_id = record_id_for(&parent_src)
        .ok_or_else(|| format!("cannot derive a parent id for `{parent_src}`"))?;
    let child_ids: Vec<String> =
        children.iter().filter_map(|c| c.get("id").and_then(Value::as_str).map(str::to_string)).collect();
    // parent -> each child, and keep any original composes that did not point at a child.
    let mut composes: Vec<Value> = child_ids.iter().cloned().map(Value::String).collect();
    if let Some(orig) = record.get("composes").and_then(Value::as_array) {
        for c in orig {
            if let Some(s) = c.as_str() {
                if !child_ids.iter().any(|id| id == s) {
                    composes.push(Value::String(s.to_string()));
                }
            }
        }
    }

    // Carry the flat record's fields (summary, tests, domain, moduleVis, …) and override what the split
    // changes. Write-bookkeeping is stripped by the CLI on its way into the committed store.
    let mut parent = record.clone();
    parent["id"] = Value::String(parent_id);
    parent["src"] = Value::String(parent_src);
    parent["folder"] = Value::String(dir.to_string());
    parent["composes"] = Value::Array(composes);
    parent["code"] = Value::String(parent_code);
    if consumer_only {
        let mut attrs = parent
            .get("moduleAttrs")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        let allow = Value::String("#[allow(unused_imports)]".to_string());
        if !attrs.contains(&allow) {
            attrs.push(allow);
        }
        parent["moduleAttrs"] = Value::Array(attrs);
    }

    Ok(ExtractionPlan { flat_id, parent, children })
}

#[cfg(test)]
mod tests {
use super::*;

    // A flat record shaped like the real by-hand decompose targets: a `//!` header, a `use`, a retained
    // struct + impl + const + private helper, and a mix of pure leaves — one self-contained, one that
    // needs the parent's import, one calling a sibling leaf, and two that MUST be refused.
    fn fixture() -> Value {
        let code = "\
//! Widget helpers.
//!
//! Second header line.

use serde_json::Value;

const LIMIT: usize = 4;

pub struct Widget {
    pub n: usize,
}

impl Widget {
    pub fn bump(&mut self) {
        self.n += 1;
    }
}

fn secret(n: usize) -> usize {
    n * LIMIT
}

/// Double a number.
pub fn double(x: usize) -> usize { x + x }

/// Name of a value — needs the parent's `Value` import.
pub(crate) fn name_of(v: &Value) -> String {
    v.get(\"n\").and_then(Value::as_str).unwrap_or(\"\").to_string()
}

/// Triple via double.
pub fn triple(x: usize) -> usize { double(x) + x }

/// Uses the private const-backed helper — must be refused.
pub fn scaled(n: usize) -> usize { secret(n) + 1 }

pub fn io_write(p: &str) {
    std::fs::write(p, \"x\").ok();
}
";
        serde_json::json!({
            "id": "bsc-demo--widget.rs",
            "tech": "rust",
            "role": "algorithm",
            "name": "widget",
            "src": "crates/bsc-demo/src/widget.rs",
            "feature": "core",
            "composes": ["bsc-demo--other.rs"],
        })
        .as_object()
        .cloned()
        .map(|mut m| {
            m.insert("code".to_string(), Value::String(code.to_string()));
            Value::Object(m)
        })
        .unwrap()
    }

    fn child<'a>(plan: &'a ExtractionPlan, id: &str) -> &'a Value {
        plan.children
            .iter()
            .find(|c| c.get("id").and_then(Value::as_str) == Some(id))
            .unwrap_or_else(|| panic!("no child `{id}` in plan (have {:?})",
                plan.children.iter().filter_map(|c| c.get("id").and_then(Value::as_str)).collect::<Vec<_>>()))
    }

    #[test]
    fn record_id_hyphenates_the_functions_underscores() {
        assert_eq!(record_id_for("crates/bsc-demo/src/widget/name_of.rs").as_deref(),
                   Some("bsc-demo--widget--name-of.rs"));
        assert_eq!(record_id_for("crates/bsc-fin/src/balance.rs").as_deref(),
                   Some("bsc-fin--balance.rs"));
        assert_eq!(record_id_for("crates/bsc-demo/src/widget/mod.rs").as_deref(),
                   Some("bsc-demo--widget--mod.rs"));
    }

    #[test]
    fn extract_mints_hyphenated_child_ids_the_parent_reexports_and_removes_the_flat_record() {
        let plan = plan_extraction(
            &fixture(),
            &["double".into(), "name_of".into(), "triple".into()],
        )
        .expect("clean pure leaves extract");

        assert_eq!(plan.flat_id, "bsc-demo--widget.rs");

        // hyphenated child ids
        let ids: Vec<&str> =
            plan.children.iter().filter_map(|c| c.get("id").and_then(Value::as_str)).collect();
        assert_eq!(ids, vec![
            "bsc-demo--widget--double.rs",
            "bsc-demo--widget--name-of.rs",
            "bsc-demo--widget--triple.rs",
        ]);

        // src / name keep underscores; module is private; feature carried
        let nm = child(&plan, "bsc-demo--widget--name-of.rs");
        assert_eq!(nm.get("name").and_then(Value::as_str), Some("name_of"));
        assert_eq!(nm.get("src").and_then(Value::as_str), Some("crates/bsc-demo/src/widget/name_of.rs"));
        assert_eq!(nm.get("moduleVis").and_then(Value::as_str), Some("private"));
        assert_eq!(nm.get("feature").and_then(Value::as_str), Some("core"));

        // parent is the --mod.rs, composes -> every child + the surviving original edge
        assert_eq!(plan.parent.get("id").and_then(Value::as_str), Some("bsc-demo--widget--mod.rs"));
        assert_eq!(plan.parent.get("src").and_then(Value::as_str), Some("crates/bsc-demo/src/widget/mod.rs"));
        let composes: Vec<&str> =
            plan.parent.get("composes").and_then(Value::as_array).unwrap().iter()
                .filter_map(Value::as_str).collect();
        assert!(composes.contains(&"bsc-demo--widget--double.rs"));
        assert!(composes.contains(&"bsc-demo--widget--name-of.rs"));
        assert!(composes.contains(&"bsc-demo--widget--triple.rs"));
        assert!(composes.contains(&"bsc-demo--other.rs"), "the original non-child edge survives");

        // parent keeps the header + re-exports (matching vis) after it, and keeps the retained items
        let pc = plan.parent.get("code").and_then(Value::as_str).unwrap();
        assert!(pc.starts_with("//! Widget helpers."), "header preserved");
        assert!(pc.contains("pub use double::double;"));
        assert!(pc.contains("pub(crate) use name_of::name_of;"));
        assert!(pc.contains("pub use triple::triple;"));
        // header comes before the re-exports
        assert!(pc.find("//! Second header line.").unwrap() < pc.find("pub use double").unwrap());
        // retained items stay
        assert!(pc.contains("pub struct Widget"));
        assert!(pc.contains("const LIMIT: usize = 4;"));
        assert!(pc.contains("fn secret(n: usize)"));
        assert!(pc.contains("pub fn scaled"));
        // moved bodies are gone from the parent
        assert!(!pc.contains("pub fn double(x: usize) -> usize { x + x }"));
        assert!(!pc.contains("fn triple"));

        // consumer-only re-exports -> the allow attr is added
        let attrs: Vec<&str> = plan.parent.get("moduleAttrs").and_then(Value::as_array).unwrap()
            .iter().filter_map(Value::as_str).collect();
        assert!(attrs.contains(&"#[allow(unused_imports)]"));
    }

    /// MODULE INCEPTION IS REFUSED, not renamed. A leaf named after its own module produces `mod x`
    /// inside `mod x`, which clippy denies workspace-wide. MEASURED: 2 of 111 leaves on the backlog.
    #[test]
    fn a_leaf_named_after_its_own_module_is_refused() {
        let record = serde_json::json!({
            "id": "logs--pending.rs", "tech": "rust", "src": "crates/logs/src/pending.rs",
            "code": "pub fn pending(x: usize) -> usize { x }\npub fn other(x: usize) -> usize { x }\n",
        });
        let err = super::plan_extraction(&record, &["pending".to_string()]).expect_err("must refuse");
        assert!(err.contains("module_inception"), "{err}");
        assert!(err.contains("pending"), "it must name the function: {err}");
        // …and the sibling leaf is still extractable, so the rule costs only the clashing name.
        assert!(super::plan_extraction(&record, &["other".to_string()]).is_ok());
    }

    /// TWO TOP-LEVEL FUNCTIONS SHARING A NAME are `#[cfg]`-gated variants of one function, and both
    /// would become the SAME child record id — one silently overwriting the other. Both are dropped,
    /// not just the second: extracting half of a cfg pair is worse than extracting neither.
    #[test]
    fn a_cfg_gated_name_pair_is_not_extractable_on_either_side() {
        let code = "\
pub fn plain(x: usize) -> usize { x + x }\n\n\
#[cfg(unix)]\npub fn signal_number(x: usize) -> usize { x }\n\n\
#[cfg(windows)]\npub fn signal_number(x: usize) -> usize { x + 1 }\n";
        assert_eq!(super::extractable_leaves(code, "rust"), vec!["plain"]);
    }

    /// A BODY REACHING THROUGH `super::` IS NOT EXTRACTABLE. Moving the function one module deeper
    /// changes what `super` means, and the path silently resolves to nothing:
    /// `error[E0433]: cannot find `studio_ws` in `super``. MEASURED: 3 functions in 1 record of 39.
    #[test]
    fn a_fn_reaching_through_super_is_not_an_extractable_leaf() {
        let code = "\
pub fn plain(x: usize) -> usize { x + x }\n\n\
pub fn reaches(x: usize) -> usize { super::helper::thing(x) }\n";
        assert_eq!(super::extractable_leaves(code, "rust"), vec!["plain"]);
    }

    /// A `#[tauri::command]` FN IS NOT AN EXTRACTABLE LEAF, however pure its body reads.
    ///
    /// The macro emits `__cmd__<name>` beside the function, and `tauri::generate_handler![m::name]`
    /// resolves it in module `m` — so moving the function into a child record leaves the generated
    /// items behind. MEASURED on the method-leaf backlog: 24 such functions across 12 records were
    /// proposed, and moving them produced 60 `E0433`s in `base-studio-code`.
    ///
    /// The neighbouring plain function must still be proposed, or the rule would cost every honest leaf
    /// in a commands module.
    #[test]
    fn a_command_attributed_fn_is_not_an_extractable_leaf() {
        let code = "\
/// Pure.\npub fn double(x: usize) -> usize { x + x }\n\n\
/// A Tauri command.\n#[tauri::command]\npub fn record_attestations(x: usize) -> usize { x + 1 }\n";
        let leaves = super::extractable_leaves(code, "rust");
        assert_eq!(leaves, vec!["double"], "the command must not be proposed: {leaves:?}");
    }

    /// …and a comment between the attribute and the fn must not hide it — the walk has to scan past
    /// comments exactly as `is_test_attributed` does.
    #[test]
    fn a_comment_between_the_attribute_and_the_fn_does_not_hide_it() {
        let code = "\
#[tauri::command]\n// why this is a command\npub fn record_attestations(x: usize) -> usize { x + 1 }\n";
        assert!(super::extractable_leaves(code, "rust").is_empty(), "the attribute still applies");
    }

    /// AN INNER ATTRIBUTE IS PART OF THE PREAMBLE. `#![allow(…)]` must precede every item in its
    /// module, so inserting the re-exports above one moves it after an item and the crate stops
    /// compiling with `error: an inner attribute is not permitted in this context`.
    ///
    /// MEASURED on the extraction backlog: 1 record of 39 carried one, and it broke the workspace
    /// build — a 1-in-39 shape is exactly the kind a batch run buries.
    #[test]
    fn the_re_exports_land_after_an_inner_attribute_not_before_it() {
        let code = "//! Header.\n\n// why this is allowed\n#![allow(dead_code)]\n\npub fn double(x: usize) -> usize { x + x }\n";
        let at = super::header_end_byte(code);
        let (before, after) = code.split_at(at);
        assert!(before.contains("#![allow(dead_code)]"), "the attribute is INSIDE the preamble: {before:?}");
        assert!(after.contains("pub fn double"), "and the body follows it: {after:?}");
        assert!(
            !after.contains("#!["),
            "nothing an insertion could displace may remain after the split: {after:?}"
        );
    }

    /// A `//` comment sitting directly above the first item belongs to THAT ITEM, so the preamble must
    /// not swallow it — the re-exports would otherwise be wedged between a comment and what it explains.
    #[test]
    fn a_comment_attached_to_the_first_item_is_not_preamble() {
        let code = "//! Header.\n\n// this explains double\npub fn double(x: usize) -> usize { x + x }\n";
        let (before, after) = code.split_at(super::header_end_byte(code));
        assert!(before.trim_end().ends_with("//! Header."), "preamble stops at the header: {before:?}");
        assert!(after.starts_with("\n// this explains double"), "the comment stays with its item: {after:?}");
    }

    #[test]
    fn a_private_leaf_is_bumped_and_use_super_is_added_only_when_a_parent_name_is_referenced() {
        let plan = plan_extraction(
            &fixture(),
            &["double".into(), "name_of".into(), "triple".into()],
        )
        .unwrap();

        // self-contained pure fn: NO `use super::*`, exact body
        let d = child(&plan, "bsc-demo--widget--double.rs");
        assert_eq!(
            d.get("code").and_then(Value::as_str).unwrap(),
            "/// Double a number.\npub fn double(x: usize) -> usize { x + x }\n"
        );
        assert!(d.get("composes").and_then(Value::as_array).unwrap().is_empty());

        // references the parent's `Value` import -> `use super::*` prepended, vis kept pub(crate)
        let nm = child(&plan, "bsc-demo--widget--name-of.rs");
        let nmc = nm.get("code").and_then(Value::as_str).unwrap();
        assert!(nmc.starts_with("use super::*;\n\n"), "needs the parent import: {nmc}");
        assert!(nmc.contains("pub(crate) fn name_of"));

        // triple calls a sibling leaf -> `use super::*` + a child->child compose edge
        let t = child(&plan, "bsc-demo--widget--triple.rs");
        let tc = t.get("code").and_then(Value::as_str).unwrap();
        assert!(tc.starts_with("use super::*;\n\n"));
        let tcomp: Vec<&str> =
            t.get("composes").and_then(Value::as_array).unwrap().iter().filter_map(Value::as_str).collect();
        assert_eq!(tcomp, vec!["bsc-demo--widget--double.rs"]);
    }

    #[test]
    fn a_bare_private_fn_is_bumped_to_pub_crate() {
        // `secret` is refused (it reaches LIMIT), so prove the bump on a private leaf that is clean.
        let rec = serde_json::json!({
            "id": "bsc-demo--w.rs", "tech": "rust", "role": "algorithm", "name": "w",
            "src": "crates/bsc-demo/src/w.rs",
            "code": "//! h\nfn helper(x: u32) -> u32 { x + 1 }\npub fn other(x: u32) -> u32 { x }\n",
        });
        let plan = plan_extraction(&rec, &["helper".into()]).unwrap();
        let h = child(&plan, "bsc-demo--w--helper.rs");
        assert!(h.get("code").and_then(Value::as_str).unwrap().contains("pub(crate) fn helper"));
        // a private leaf re-exports as pub(crate)
        assert!(plan.parent.get("code").and_then(Value::as_str).unwrap()
            .contains("pub(crate) use helper::helper;"));
    }

    #[test]
    fn extract_refuses_and_says_why() {
        // IO / effectful
        let e = plan_extraction(&fixture(), &["io_write".into()]).unwrap_err();
        assert!(e.contains("std::fs") || e.contains("IO"), "reason names the impurity: {e}");

        // reaches a private parent item that stays behind
        let e = plan_extraction(&fixture(), &["scaled".into()]).unwrap_err();
        assert!(e.contains("PRIVATE") || e.contains("private"), "reason names the private coupling: {e}");

        // a private leaf that itself reaches a private const
        let e = plan_extraction(&fixture(), &["secret".into()]).unwrap_err();
        assert!(e.to_lowercase().contains("private"), "{e}");

        // a method, not a free fn
        let e = plan_extraction(&fixture(), &["bump".into()]).unwrap_err();
        assert!(e.contains("no top-level free function"), "{e}");

        // no such fn
        let e = plan_extraction(&fixture(), &["nope".into()]).unwrap_err();
        assert!(e.contains("no top-level free function"), "{e}");

        // already a dir-module
        let mut modrec = fixture();
        modrec["id"] = Value::String("bsc-demo--widget--mod.rs".into());
        modrec["src"] = Value::String("crates/bsc-demo/src/widget/mod.rs".into());
        let e = plan_extraction(&modrec, &["double".into()]).unwrap_err();
        assert!(e.contains("already a `--mod.rs`"), "{e}");
    }
}
}

#[cfg(test)]
mod tests {
    use super::*;
